hoisted_loop_expressions: crate::FastHashMap<Handle<crate::Expression>, String>,
arithmetic_control_helpers:
    crate::FastHashMap<(back::FunctionType, Handle<crate::Expression>), String>,
/// See [`Writer::set_experimental_arithmetic_control_inline_isolated`].
arithmetic_control_inline_isolated: bool,
/// Refusing analysis rules of the last `write`, one per refused function.
arithmetic_control_inline_refusals: Vec<u32>,
