/// Experimental capability (requires
/// `Options::experimental_arithmetic_control_out_results`; default off).
/// For a function whose controlled operations are provably isolated,
/// write the same scalar operand-array helpers without `[noinline]`.
///
/// DXC inlines ordinary helpers before its precise propagation pass, so
/// the `precise` result then also marks the operations computing the
/// helper operands. A function qualifies only if every operation DXC could
/// mark that way is itself controlled or exact (sign, bit, integer,
/// selection, conversion, min/max/clamp/saturate and rounding operations):
/// a straight-line body (Emit/Store/Block/Return only), and a backward
/// slice of every controlled operation - through every store to a matching
/// local or private location regardless of program order - that reaches no
/// other floating-point arithmetic or comparison, derivative, call result
/// or non-entry argument. Otherwise the `[noinline]` helpers are written
/// unchanged. The written text differs, so text-keyed caches separate it.
pub fn set_experimental_arithmetic_control_inline_isolated(&mut self, enabled: bool) -> &mut Self {
    self.arithmetic_control_inline_isolated = enabled;
    self
}

/// Diagnostic: for each function of the last `write` that has controls but
/// kept its `[noinline]` helpers under the switch, the refusing analysis
/// rule (a source line of this writer).
pub fn experimental_arithmetic_control_inline_refusals(&self) -> &[u32] {
    &self.arithmetic_control_inline_refusals
}

self.arithmetic_control_helpers.clear();
self.arithmetic_control_inline_refusals.clear();
self.arithmetic_control_by_value.clear();
self.hoisted_loop_expressions.clear();

self.need_bake_expressions
    .extend(func.expression_controls.keys().copied());
for &handle in func.expression_controls.keys() {
    if let Expression::Math {
        fun: crate::MathFunction::Exp2 | crate::MathFunction::Floor | crate::MathFunction::Sin | crate::MathFunction::Cos | crate::MathFunction::InverseSqrt,
        arg,
        ..
    } = func.expressions[handle]
    {
        self.need_bake_expressions.insert(arg);
        continue;
    }
    let (left, right) = back::arithmetic_control_operands(&func.expressions[handle]);
    self.need_bake_expressions.extend([left, right]);
