/// A real non-inlined function bounds HLSL's backward `precise`
/// propagation. Ordinary helpers and temporaries do not provide this
/// boundary: FXC inlines even `[noinline]`, so this requires SM 6 / DXC.
fn write_arithmetic_control_helpers(
    &mut self,
    module: &Module,
    ty: back::FunctionType,
    function: &crate::Function,
    info: &valid::FunctionInfo,
) -> BackendResult {
    // Drop the boundary only where it provably changes no marking.
    let isolated = self.arithmetic_control_inline_isolated
        && !function.expression_controls.is_empty()
        && match super::arithmetic_control::controls_are_isolated(module, ty, function, info) {
            Ok(()) => true,
            Err(rule) => {
                self.arithmetic_control_inline_refusals.push(rule);
                false
            }
        };
    let noinline = if isolated { "" } else { "[noinline]\n" };
    // A refused function under the switch keeps its `[noinline]`
    // boundary, so DXC's precise propagation stops exactly where it stops for
    // the operand-array form, but its helpers take their operands by value and
    // return the result. The array form is an indexable temporary that the
    // NVIDIA D3D12 compiler keeps in memory around every call (the foliage
    // prepass VS: 220 helpers, about 12 ms); by-value calls need no memory.
    // Isolated functions and the default writer keep the operand-array form.
    let by_value = self.arithmetic_control_inline_isolated && !isolated;
    if by_value {
        self.arithmetic_control_by_value.insert(ty);
    }
    let operand = |index: usize| {
        if by_value {
            alloc::format!("operand{index}")
        } else {
            alloc::format!("operands[{index}]")
        }
    };
    let float_parameters = |arity: usize| {
        if by_value {
            (0..arity)
                .map(|index| alloc::format!("float operand{index}"))
                .collect::<Vec<_>>()
                .join(", ")
        } else {
            alloc::format!("inout float operands[{arity}]")
        }
    };
    let (result_type, result_tail) = if by_value {
        ("float", "return result;")
    } else {
        ("void", "operands[0] = result;")
    };
    for &handle in function.expression_controls.keys() {
        let expression = &function.expressions[handle];
        if matches!(
            expression,
            crate::Expression::Math {
                fun: crate::MathFunction::Exp2,
                ..
            }
        ) {
            let name = self.namer.call("naga_exp2_no_refactoring_v1");
            writeln!(self.out, "{noinline}{result_type} {name}({}) {{\n    precise float result = exp2({});\n    {result_tail}\n}}", float_parameters(1), operand(0))?;
            self.arithmetic_control_helpers.insert((ty, handle), name);
            continue;
        }
        if matches!(
            expression,
            crate::Expression::Math {
                fun: crate::MathFunction::Floor,
                ..
            }
        ) {
            // Validated f32 scalar/vector: floor is component-wise, so the
            // result writer calls this scalar helper once per lane.
            let name = self.namer.call("naga_floor_no_refactoring_v1");
            writeln!(self.out, "{noinline}{result_type} {name}({}) {{\n    precise float result = floor({});\n    {result_tail}\n}}", float_parameters(1), operand(0))?;
            self.arithmetic_control_helpers.insert((ty, handle), name);
            continue;
        }
        if let crate::Expression::Math {
            fun: fun @ (crate::MathFunction::Sin | crate::MathFunction::Cos | crate::MathFunction::InverseSqrt),
            ..
        } = *expression
        {
            // Validated f32 scalar/vector tolerance op; one scalar call per lane.
            let (base, call) = match fun {
                crate::MathFunction::Sin => ("naga_sin_no_refactoring_v1", "sin"),
                crate::MathFunction::Cos => ("naga_cos_no_refactoring_v1", "cos"),
                _ => ("naga_rsqrt_no_refactoring_v1", "rsqrt"),
            };
            let name = self.namer.call(base);
            writeln!(self.out, "{noinline}{result_type} {name}({}) {{\n    precise float result = {call}({});\n    {result_tail}\n}}", float_parameters(1), operand(0))?;
            self.arithmetic_control_helpers.insert((ty, handle), name);
            continue;
        }
        if matches!(
            expression,
            crate::Expression::Binary {
                op: crate::BinaryOperator::Less,
                ..
            }
        ) {
            // Validated f32 scalar/vector ordered `<` with a bool
            // result; the result writer calls this scalar helper once per lane.
            let name = self.namer.call("naga_less_no_refactoring_v1");
            if by_value {
                writeln!(self.out, "{noinline}bool {name}({}) {{\n    precise bool less = {} < {};\n    return less;\n}}", float_parameters(2), operand(0), operand(1))?;
            } else {
                writeln!(self.out, "{noinline}void {name}(inout float operands[2], out bool result) {{\n    precise bool less = operands[0] < operands[1];\n    result = less;\n}}")?;
            }
            self.arithmetic_control_helpers.insert((ty, handle), name);
            continue;
        }
        let (left, _) = back::arithmetic_control_operands(expression);
        let argument_type = info[left].ty.inner_with(&module.types);
        let scalar = argument_type.scalar().unwrap();
        if scalar.width == 2 && self.options.shader_model < ShaderModel::V6_2 {
            return Err(Error::UnsupportedArithmeticControls);
        }
        let scalar_type = TypeInner::Scalar(scalar);
        let dot_size = match *expression {
            crate::Expression::Math {
                fun: crate::MathFunction::Dot,
                ..
            } => match *argument_type {
                TypeInner::Vector { size, .. } => Some(size),
                _ => unreachable!("validated dot control"),
            },
            _ => None,
        };
        if dot_size.is_some() && scalar == Scalar::F64 {
            return Err(Error::UnsupportedArithmeticControls);
        }
        let name = self.namer.call("naga_no_contraction");
        write!(self.out, "{noinline}")?;
        let arity = 2 * dot_size.map_or(1, |size| size as u8);
        if by_value {
            self.write_value_type(module, &scalar_type)?;
            write!(self.out, " {name}(")?;
            for index in 0..arity {
                if index != 0 {
                    write!(self.out, ", ")?;
                }
                self.write_value_type(module, &scalar_type)?;
                write!(self.out, " operand{index}")?;
            }
            writeln!(self.out, ") {{")?;
        } else {
            write!(self.out, "void {name}(inout ")?;
            self.write_value_type(module, &scalar_type)?;
            writeln!(self.out, " operands[{arity}]) {{")?;
        }
        write!(self.out, "{}precise ", back::INDENT)?;
        self.write_value_type(module, &scalar_type)?;
        write!(self.out, " result = ")?;
        match *expression {
            crate::Expression::Binary { op, .. } if scalar.kind == ScalarKind::Sint => {
                let (to_signed, to_unsigned) = match scalar.width {
                    2 => ("int16_t", "uint16_t"),
                    4 => ("asint", "asuint"),
                    8 => ("int64_t", "uint64_t"),
                    _ => unreachable!("validated signed integer width"),
                };
                write!(
                    self.out,
                    "{to_signed}({to_unsigned}({}) {} {to_unsigned}({}))",
                    operand(0),
                    back::binary_operation_str(op),
                    operand(1)
                )?;
            }
            crate::Expression::Binary { op, .. } => {
                write!(
                    self.out,
                    "{} {} {}",
                    operand(0),
                    back::binary_operation_str(op),
                    operand(1)
                )?;
            }
            crate::Expression::Math {
                fun: crate::MathFunction::Dot,
                ..
            } => {
                write!(self.out, "dot(")?;
                let size = dot_size.unwrap() as u8;
                for side in 0..2 {
                    if side != 0 {
                        write!(self.out, ", ")?;
                    }
                    self.write_value_type(module, argument_type)?;
                    write!(self.out, "(")?;
                    for lane in 0..size {
                        if lane != 0 {
                            write!(self.out, ", ")?;
                        }
                        write!(self.out, "{}", operand((side * size + lane) as usize))?;
                    }
                    write!(self.out, ")")?;
                }
                write!(self.out, ")")?;
            }
            _ => unreachable!("validated arithmetic control"),
        }
        writeln!(self.out, ";\n{}{result_tail}\n}}\n", back::INDENT)?;
        self.arithmetic_control_helpers.insert((ty, handle), name);
    }
    Ok(())
}

let ep_range = get_entry_points(module, self.pipeline_options.entry_point.as_ref())
    .map_err(|(stage, name)| Error::EntryPointNotFound(stage, name))?;
let reachable = module
    .has_arithmetic_controls()
    .then(|| back::reachable_functions(module, ep_range.clone()));
let has_controls = ep_range.clone().any(|index| {
    !module.entry_points[index]
        .function
        .expression_controls
        .is_empty()
}) || reachable.as_ref().is_some_and(|functions| {
    functions
        .iter()
        .any(|&handle| !module.functions[handle].expression_controls.is_empty())
});
if has_controls
    && (self.options.shader_model < ShaderModel::V6_0
        || !self.options.experimental_arithmetic_control_out_results)
{
    return Err(Error::UnsupportedArithmeticControls);
}

    if reachable
        .as_ref()
        .is_some_and(|functions| !functions.contains(&handle))
    {
        continue;
    }
    self.write_arithmetic_control_helpers(
        module,
        back::FunctionType::Function(handle),
        function,
        &module_info[handle],
    )?;
}
for index in ep_range.clone() {
    self.write_arithmetic_control_helpers(
        module,
        back::FunctionType::EntryPoint(index as u16),
        &module.entry_points[index].function,
        module_info.get_entry_point(index),
    )?;
}
for (handle, function) in module.functions.iter() {
    if reachable
        .as_ref()
        .is_some_and(|functions| !functions.contains(&handle))
    {
        continue;
    }

/// Initialize operand arrays at the producer, after baking their inputs.
fn write_arithmetic_control_result(
    &mut self,
    module: &Module,
    handle: Handle<crate::Expression>,
    name: String,
    func_ctx: &back::FunctionCtx<'_>,
    level: back::Level,
) -> BackendResult {
    use crate::Expression;
    let helper = self.arithmetic_control_helpers[&(func_ctx.ty, handle)].clone();
    let expression = &func_ctx.expressions[handle];
    let result_type = func_ctx.resolve_type(handle, &module.types);
    // A controlled comparison packs its f32 operands and
    // returns each lane through a separate bool out-result.
    let less = matches!(*expression, Expression::Binary { op: crate::BinaryOperator::Less, .. });
    let scalar_type = if less {
        let (left, _) = back::arithmetic_control_operands(expression);
        TypeInner::Scalar(func_ctx.resolve_type(left, &module.types).scalar().unwrap())
    } else {
        TypeInner::Scalar(result_type.scalar().unwrap())
    };
    let (operands, dot_size) = match *expression {
        Expression::Math {
            fun: crate::MathFunction::Exp2 | crate::MathFunction::Floor | crate::MathFunction::Sin | crate::MathFunction::Cos | crate::MathFunction::InverseSqrt,
            arg,
            ..
        } => (alloc::vec![arg], None),
        _ => {
            let (left, right) = back::arithmetic_control_operands(expression);
            let dot_size = if matches!(
                *expression,
                Expression::Math {
                    fun: crate::MathFunction::Dot,
                    ..
                }
            ) {
                match *func_ctx.resolve_type(left, &module.types) {
                    TypeInner::Vector { size, .. } => Some(size),
                    _ => return Err(Error::UnsupportedArithmeticControls),
                }
            } else {
                None
            };
            (alloc::vec![left, right], dot_size)
        }
    };
    // A runtime operand lacking its baked name has no valid dominating
    // Emit here. Do not re-evaluate it or hoist it to manufacture one.
    for &operand in &operands {
        if !self.named_expressions.contains_key(&operand)
            && !matches!(
                func_ctx.expressions[operand],
                Expression::Literal(_)
                    | Expression::Constant(_)
                    | Expression::ZeroValue(_)
                    | Expression::FunctionArgument(_)
            )
        {
            return Err(Error::UnsupportedArithmeticControls);
        }
    }
    let vector_size = match *result_type {
        TypeInner::Vector { size, .. } => Some(size),
        TypeInner::Scalar(_) => None,
        _ => return Err(Error::UnsupportedArithmeticControls),
    };
    let mut outputs = Vec::new();
    let arity = operands.len() * dot_size.map_or(1, |size| size as usize);
    let by_value = self.arithmetic_control_by_value.contains(&func_ctx.ty);
    for lane in 0..vector_size.map_or(1, |size| size as u8) {
        if by_value {
            // `T value = helper(operand, ...);` (see the helpers).
            let value = self.namer.call(if less { "naga_less_result" } else { "naga_value" });
            write!(self.out, "{level}")?;
            if less {
                write!(self.out, "bool")?;
            } else {
                self.write_value_type(module, &scalar_type)?;
            }
            write!(self.out, " {value} = {helper}(")?;
            for (side, &operand) in operands.iter().enumerate() {
                for component in 0..dot_size.map_or(1, |size| size as u8) {
                    if side != 0 || component != 0 {
                        write!(self.out, ", ")?;
                    }
                    write!(self.out, "(")?;
                    self.write_expr(module, operand, func_ctx)?;
                    write!(self.out, ")")?;
                    if dot_size.is_some() || vector_size.is_some() {
                        let component = if dot_size.is_some() { component } else { lane };
                        write!(self.out, ".{}", back::COMPONENTS[component as usize])?;
                    }
                }
            }
            writeln!(self.out, ");")?;
            outputs.push(value);
            continue;
        }
        let packet = self.namer.call("naga_operands");
        write!(self.out, "{level}")?;
        self.write_value_type(module, &scalar_type)?;
        write!(self.out, " {packet}[{arity}] = {{")?;
        for (side, &operand) in operands.iter().enumerate() {
            for component in 0..dot_size.map_or(1, |size| size as u8) {
                if side != 0 || component != 0 {
                    write!(self.out, ", ")?;
                }
                write!(self.out, "(")?;
                self.write_expr(module, operand, func_ctx)?;
                write!(self.out, ")")?;
                if dot_size.is_some() || vector_size.is_some() {
                    let component = if dot_size.is_some() { component } else { lane };
                    write!(self.out, ".{}", back::COMPONENTS[component as usize])?;
                }
            }
        }
        if less {
            let out = self.namer.call("naga_less_result");
            writeln!(self.out, "}};\n{level}bool {out};\n{level}{helper}({packet}, {out});")?;
            outputs.push(out);
            continue;
        }
        writeln!(self.out, "}};\n{level}{helper}({packet});")?;
        outputs.push(format!("{packet}[0]"));
    }
    write!(self.out, "{level}")?;
    if !self.hoisted_loop_expressions.contains_key(&handle) {
        self.write_value_type(module, result_type)?;
        write!(self.out, " ")?;
    }
    write!(self.out, "{name} = ")?;
    if vector_size.is_some() {
        self.write_value_type(module, result_type)?;
        writeln!(self.out, "({});", outputs.join(", "))?;
    } else {
        writeln!(self.out, "{};", outputs[0])?;
    }
    self.named_expressions.insert(handle, name);
    Ok(())
}

if self
    .arithmetic_control_helpers
    .contains_key(&(func_ctx.ty, handle))
{
    self.write_arithmetic_control_result(
        module, handle, name, func_ctx, level,
    )?;
    continue;
}

let mut hoisted = Vec::new();
if gate_name.is_some()
    && self
        .arithmetic_control_helpers
        .keys()
        .any(|&(ty, _)| ty == func_ctx.ty)
{
    for statement in body.iter() {
        let handles: Vec<_> = match *statement {
            Statement::Emit(ref range) => range
                .clone()
                .filter(|handle| {
                    func_ctx
                        .resolve_type(*handle, &module.types)
                        .pointer_space()
