/// Emit identical words and an execution-local correspondence relation.
/// Hash returned words as little-endian bytes alongside the report externally.
pub fn write_vec_with_report(module: &crate::Module, info: &crate::valid::ModuleInfo,
    options: &Options, pipeline_options: Option<&PipelineOptions>)
    -> Result<(Vec<u32>, crate::correspondence::EmissionReport), Error> {
    use crate::correspondence::*;
    let mut report = EmissionReport { revision: REVISION, values: Vec::new(), arithmetic: Vec::new(), exp2: Vec::new(), floor: Vec::new(), compare: Vec::new(), r2_865: None, tolerance: Vec::new(), strict_bitcasts865: Vec::new() };
    for (owner, fun) in module.functions.iter().map(|(h,f)|(Owner::Function(h),f)).chain(
        module.entry_points.iter().enumerate().map(|(i,e)|(Owner::EntryPoint(i), &e.function))) {
        report.values.extend(fun.expressions.iter().map(|(expression,_)|
            (ExpressionRef { owner, expression }, EmittedValue::OwnerNotEmitted)));
    }
    let mut w = Writer::new(options)?;
    w.correspondence = Some(report);
    let mut words = Vec::new();
    w.write(module, info, pipeline_options, &options.debug_info, &mut words)?;
    Ok((words, w.correspondence.take().unwrap()))
}
