impl Writer {
    /// R2 carrier rule for a module that declares FloatControls2.
    pub(super) fn finish_r2_865(&mut self) -> Result<(), Error> {
        self.r2_last865 = None;
        if !self.capabilities_used.contains(&spirv::Capability::FloatControls2) {
            return Ok(());
        }
        let mut targets = self.r2_no_contraction865.clone();
        targets.sort_by_key(|t| t.0);
        let (mut fp, mut dropped) = (Vec::new(), Vec::new());
        for &(index, id, float) in &targets {
            if float {
                self.annotations[index] = Instruction::decorate(id, spirv::Decoration::FPFastMathMode, &[0x7]);
                fp.push(id);
            } else {
                dropped.push(id);
            }
        }
        for &(index, _, float) in targets.iter().rev() {
            if !float {
                self.annotations.remove(index);
            }
        }
        let f32_id = self.get_f32_type_id();
        let u32_id = self.get_u32_type_id();
        let constant = self.id_gen.next();
        let declarations = &mut self.logical_layout.declarations;
        let (mut at, mut after_constants, mut after_u32) = (0usize, 0usize, 0usize);
        while at < declarations.len() {
            let count = (declarations[at] >> 16) as usize;
            let op = declarations[at] & 0xffff;
            if count == 0 {
                return Err(Error::Validation("R2 declaration scan"));
            }
            if matches!(op, 41 | 42 | 43 | 44 | 46) {
                after_constants = at + count;
            }
            if op == 21 && declarations.get(at + 1) == Some(&u32_id) {
                after_u32 = at + count;
            }
            at += count;
        }
        let position = after_constants.max(after_u32);
        declarations.splice(position..position, [(4 << 16) | 43, u32_id, constant, 0x7000F]);
        for &entry in &self.r2_entry_ids865 {
            self.logical_layout
                .execution_modes
                .extend([(5 << 16) | 331, entry, spirv::ExecutionMode::FPFastMathDefault as u32, f32_id, constant]);
        }
        let report = crate::correspondence::R2Emission865 {
            fp_fast_math_0x7: fp,
            dropped_integer_no_contraction: dropped,
            entry_ids: self.r2_entry_ids865.clone(),
            f32_type_id: f32_id,
            u32_type_id: u32_id,
            default_constant_id: constant,
        };
        if let Some(r) = self.correspondence.as_mut() {
            r.r2_865 = Some(report.clone());
        }
        self.r2_last865 = Some(report);
        Ok(())
    }

    /// The R2 rewrite of the last written module, if it declared FloatControls2.
    pub fn r2_emission865(&self) -> Option<&crate::correspondence::R2Emission865> {
        self.r2_last865.as_ref()
    }
}

