//! Execution-local correspondence, revision 2. No source-language provenance is stored.
//!
//! Handles are valid only for the exact input/output module pair of the reported
//! execution. Clone receipts with modules; invalidate reports on any subsequent
//! mutation. Callers must bind reports to their module identity and SHA256 of
//! SPIR-V words serialized as little-endian u32 bytes. No digest is invented here.
use alloc::vec::Vec;
use crate::{Expression, Function, Handle};

pub const REVISION: u32 = 2;
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Owner { Function(Handle<Function>), EntryPoint(usize) }
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct ExpressionRef { pub owner: Owner, pub expression: Handle<Expression> }
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Disposition<T> { Survives(T), Removed }
#[derive(Clone, Debug)]
pub struct HandleRemap<T> { pub old: Handle<T>, pub new: Disposition<Handle<T>> }
#[derive(Clone, Debug)]
pub struct OwnerRemap {
    pub old: Owner,
    pub new: Disposition<Owner>,
    pub expressions: Vec<(Handle<Expression>, Disposition<ExpressionRef>)>,
}
#[derive(Clone, Debug)]
pub struct CompactionReport {
    pub revision: u32,
    pub owners: Vec<OwnerRemap>,
    pub types: Vec<HandleRemap<crate::Type>>,
    pub globals: Vec<HandleRemap<crate::GlobalVariable>>,
    pub constants: Vec<HandleRemap<crate::Constant>>,
    pub overrides: Vec<HandleRemap<crate::Override>>,
    pub global_expressions: Vec<HandleRemap<Expression>>,
}
/// Exact direct instruction observed at emission, not reconstructed from words.
#[derive(Clone, Debug)]
pub struct EmittedArithmetic {
    pub producer: ExpressionRef,
    pub opcode: u32,
    pub type_id: u32,
    pub result_id: u32,
    pub arguments: [(ExpressionRef, u32); 2],
}
#[derive(Clone, Debug)]
pub enum EmittedValue {
    /// The owner was excluded by the writer's actual selection policy.
    OwnerNotEmitted,
    /// Owner emitted, but no cached value ID (dead or pointer-only expression).
    NoValueId,
    /// Terminal cached value only. May alias other expressions, or be the final
    /// result of multiple lowering instructions. Not a one-to-one instruction map.
    Value(u32),
}
#[derive(Clone, Debug)]
pub struct EmissionReport {
    pub exp2: Vec<EmittedExp2>,
    /// Every emitted GLSL.std.450 Floor, with its actual control.
    pub floor: Vec<EmittedFloor>,
    /// Every emitted float comparison, with its actual control.
    pub compare: Vec<EmittedCompare865>,
    /// The R2 carrier rewrite of this module (FloatControls2 modules only).
    pub r2_865: Option<R2Emission865>,
    /// Every emitted GLSL Sin/Cos/InverseSqrt and OpFDiv, with its control.
    pub tolerance: Vec<EmittedTolerance865>,
    /// R3: every strict OpBitcast (expression, result id).
    pub strict_bitcasts865: Vec<(ExpressionRef, u32)>,
    pub revision: u32,
    pub values: Vec<(ExpressionRef, EmittedValue)>,
    /// Direct Add/Sub/Mul and float Dot only; other lowering is unfinished.
    pub arithmetic: Vec<EmittedArithmetic>,
}
#[derive(Clone, Debug)]
pub enum ImportedArithmetic {
    Direct {
        function_id: u32, result_id: u32, type_id: u32,
        producer: ExpressionRef, arguments: [(u32, ExpressionRef); 2],
    },
    /// No successful mapping is asserted for sign adaptation, spill/reload or
    /// an unexpected postprocessing change. The result ID remains inventoried.
    Unsupported { function_id: u32, result_id: u32 },
}
#[derive(Clone, Debug)]
pub struct ImportReport {
    /// Sample mapping capability; revision0/missing refuses sample joins.
    pub sample_revision: u32,
    pub samples648: Vec<ImportedSample648>,
    /// Additive selection/store trace revision; phi and spill functions refuse.
    pub flow_revision: u32,
    pub flow: Vec<ImportedFlow>,
    pub flow_adapted_functions: Vec<u32>,
    pub exp2: Vec<ImportedExp2>,
    /// Every imported GLSL.std.450 Floor, with its final control.
    pub floor: Vec<ImportedFloor>,
    /// Every imported float comparison, with its final control.
    pub compare: Vec<ImportedCompare865>,
    /// The R2 carrier controls consumed by this import.
    pub r2_865: Option<R2Import865>,
    /// Every imported GLSL Sin/Cos/InverseSqrt and OpFDiv, with its control.
    pub tolerance: Vec<ImportedTolerance865>,
    /// R3: every strict OpBitcast (result id, expression), adjacency verified.
