/// Parser events retain original IDs and actual final IR handles. `direct`
/// refuses operand spills or postprocessing changes. Callers must also check
/// final statement placement and reject functions in `flow_adapted_functions`.
#[derive(Clone, Debug)]
pub enum ImportedFlow {
    /// A two-argument value call, checked against the final patched callee/result.
    BinaryCall { function_id: u32, callee_id: u32, callee: Handle<Function>, result_id: u32,
        result: ExpressionRef, argument_ids: [u32; 2], arguments: [ExpressionRef; 2], direct: bool },
    Selection { function_id: u32, condition_id: u32, condition: ExpressionRef, direct: bool },
    Store { function_id: u32, pointer_id: u32, value_id: u32,
        pointer: ExpressionRef, value: ExpressionRef, direct: bool },
}
/// Classification for one requested producer. `ValueOnly` explicitly refuses
/// instruction-level correspondence (aliases and expanded lowering included).
#[derive(Clone, Copy, Debug)]
pub enum ArithmeticEmission<'a> {
    Direct(&'a EmittedArithmetic),
    ValueOnly(u32),
    OwnerNotEmitted,
    NoValueId,
    UnknownSource,
}
impl EmissionReport {
    pub fn producer(&self, source: ExpressionRef) -> ArithmeticEmission<'_> {
        if let Some(a) = self.arithmetic.iter().find(|a| a.producer == source) {
            return ArithmeticEmission::Direct(a);
        }
        match self.values.iter().find(|(s,_)| *s == source).map(|(_,v)| v) {
            Some(EmittedValue::Value(id)) => ArithmeticEmission::ValueOnly(*id),
            Some(EmittedValue::OwnerNotEmitted) => ArithmeticEmission::OwnerNotEmitted,
            Some(EmittedValue::NoValueId) => ArithmeticEmission::NoValueId,
            None => ArithmeticEmission::UnknownSource,
        }
    }
}

