    arguments: [Handle<crate::Expression>; 2], ids: [u32; 2], direct: bool,
    control: Option<crate::ArithmeticControl>,
}

struct PendingExp2 {
    function_id: u32, result_id: u32, type_id: u32, set_id: u32, instruction: u32,
    producer: Handle<crate::Expression>, expected: crate::Expression,
    argument: Handle<crate::Expression>, input_id: u32, direct: bool,
    control: Option<crate::ArithmeticControl>,
}

#[derive(Clone)]
struct PendingSample648 {
    function_id:u32, sample_id:u32, type_id:u32, sample:Handle<crate::Expression>, expected:crate::Expression,
    coordinate:(u32,Handle<crate::Expression>), lod:(u32,Handle<crate::Expression>), expected_coordinate:crate::Expression, expected_lod:crate::Expression, direct:bool,
}
struct PendingSampleSelection648 { sample:PendingSample648, result_id:u32, type_id:u32, result:Handle<crate::Expression>, expected:crate::Expression }
impl<I:Iterator<Item=u32>> Frontend<I>{
    fn record_sample648(&mut self,ctx:&BlockContext,id:u32,ty:u32,h:Handle<crate::Expression>,coordinate_id:u32,lod_id:u32){
        if self.correspondence.is_none(){return}
        if let crate::Expression::ImageSample{coordinate,level:crate::SampleLevel::Exact(lod),..}=ctx.expressions[h]{
            let direct=self.lookup_expression.get(&coordinate_id).is_some_and(|x|x.handle==coordinate)&&self.lookup_expression.get(&lod_id).is_some_and(|x|x.handle==lod);
            self.sample_imports648.push(PendingSample648{function_id:self.correspondence_function,sample_id:id,type_id:ty,sample:h,expected:ctx.expressions[h].clone(),coordinate:(coordinate_id,coordinate),lod:(lod_id,lod),expected_coordinate:ctx.expressions[coordinate].clone(),expected_lod:ctx.expressions[lod].clone(),direct});
        }
    }
    fn record_sample_selection648(&mut self,ctx:&BlockContext,id:u32,ty:u32,base_id:u32,h:Handle<crate::Expression>){
        if self.correspondence.is_none(){return}
        if let Some(p)=self.sample_imports648.iter().find(|p|p.function_id==self.correspondence_function&&p.sample_id==base_id){
            self.sample_selections648.push(PendingSampleSelection648{sample:p.clone(),result_id:id,type_id:ty,result:h,expected:ctx.expressions[h].clone()});
        }
    }
    fn finish_samples648(&self,module:&crate::Module)->Vec<crate::correspondence::ImportedSample648>{
        use crate::correspondence::*;
        self.sample_selections648.iter().map(|r|{let p=&r.sample;let h=self.lookup_function[&p.function_id].handle;let f=&module.functions[h];let owner=Owner::Function(h);let at=|expression|ExpressionRef{owner,expression};
            let unchanged=f.expressions.try_get(p.sample).is_ok_and(|e|e==&p.expected)&&f.expressions.try_get(r.result).is_ok_and(|e|e==&r.expected)&&f.expressions.try_get(p.coordinate.1).is_ok_and(|e|e==&p.expected_coordinate)&&f.expressions.try_get(p.lod.1).is_ok_and(|e|e==&p.expected_lod);
            let selected=matches!(r.expected,crate::Expression::AccessIndex{base,index:0}if base==p.sample);
            if p.direct&&unchanged&&selected {ImportedSample648::Direct{function_id:p.function_id,sample_id:p.sample_id,sample_type_id:p.type_id,result_id:r.result_id,type_id:r.type_id,sample:at(p.sample),producer:at(r.result),coordinate:(p.coordinate.0,at(p.coordinate.1)),lod:(p.lod.0,at(p.lod.1)),coordinate_expression:p.expected_coordinate.clone(),lod_expression:p.expected_lod.clone()}}
            else{ImportedSample648::Unsupported{function_id:p.function_id,sample_id:p.sample_id,result_id:r.result_id}}
        }).collect()
    }
}

if self.correspondence.is_some() {
    self.flow_imports.push(super::PendingFlow {
        function_id: ctx.function_id,
        kind: super::PendingFlowKind::Store { ids: [pointer_id, value_id], handles: [base_handle, value_handle] },
        direct: base_handle == base_expr.handle && value_handle == value_expr.handle,
        expected: vec![(base_handle, ctx.expressions[base_handle].clone()), (value_handle, ctx.expressions[value_handle].clone())],
    });
}

let handle = ctx.expressions.append(expr, span);
self.register_arithmetic_control(ctx, result_id, handle)?;
self.record_import(ctx, result_id, result_type_id, handle, [left_id, right_id]);

let handle865 = ctx.expressions.append(expr, span);
if inst.op == Op::Bitcast {
    self.bitcasts865.push((self.correspondence_function, result_id, handle865, strict_bitcast865));
}

let h = get_expr_handle!(arg_id, lexp);
direct_arguments &= h == lexp.handle;
argument_ids.push(arg_id);
arguments.push(h);

if self.correspondence.is_some() && arguments.len() == 2 {
    if let Some(result) = result {
        let handles = [arguments[0], arguments[1]];
        self.flow_imports.push(super::PendingFlow {
            function_id: ctx.function_id,
            kind: super::PendingFlowKind::BinaryCall { callee_id: func_id, result_id, result,
                ids: [argument_ids[0], argument_ids[1]], handles },
            direct: direct_arguments,
            expected: handles.iter().map(|h| (*h, ctx.expressions[*h].clone())).collect(),
        });
    }
}

let handle = ctx.expressions.append(expr, span);
self.register_arithmetic_control(ctx, result_id, handle)?;
if self.pending_exp2.remove(&result_id) {
    let input_type = self.lookup_expression.lookup(input_id)?.type_id;
    let scalar_f32 = |id| self.lookup_type.get(&id).is_some_and(|t|
        ctx.module.types[t.handle].inner == crate::TypeInner::Scalar(crate::Scalar::F32));
    // FPFastMathMode None is admitted only on scalar-f32 Exp2 and on
    // an f32 scalar/vector Floor whose result type equals its input.
    let inner = |id| self.lookup_type.get(&id).map(|t| ctx.module.types[t.handle].inner.clone());
    let f32_value = |id| matches!(inner(id), Some(crate::TypeInner::Scalar(crate::Scalar::F32))
        | Some(crate::TypeInner::Vector { scalar: crate::Scalar::F32, .. }));
    let control = match fun {
        Mf::Exp2 if scalar_f32(input_type) && scalar_f32(result_type_id) =>
            crate::ArithmeticControl::Exp2F32NoRefactoringV1,
        Mf::Floor if f32_value(input_type) && inner(input_type) == inner(result_type_id) =>
            crate::ArithmeticControl::FloorF32NoRefactoringV1,
        Mf::Sin | Mf::Cos | Mf::InverseSqrt if f32_value(input_type) && inner(input_type) == inner(result_type_id) =>
            crate::ArithmeticControl::ToleranceF32NoRefactoringV1,
        _ => return Err(Error::UnsupportedExp2Control(result_id)),
    };
    ctx.expression_controls.insert(handle, control);
}
if matches!(fun, Mf::Sin | Mf::Cos | Mf::InverseSqrt) && self.correspondence.is_some() {
    self.tolerance_imports865.push(super::PendingTolerance865 {
        function_id: self.correspondence_function, result_id, type_id: result_type_id,
        kind: inst_id, producer: handle, expected: ctx.expressions[handle].clone(),
        arguments: alloc::vec![(input_id, arg)],
        direct: self.lookup_expression.lookup(input_id)?.handle == arg,
        control: ctx.expression_controls.get(&handle).copied(),
    });
}
if fun == Mf::Floor && self.correspondence.is_some() {
    self.floor_imports.push(super::PendingExp2 {
        function_id: self.correspondence_function, result_id, type_id: result_type_id,
        set_id, instruction: inst_id, producer: handle, expected: ctx.expressions[handle].clone(),
        argument: arg, input_id,
        direct: self.lookup_expression.lookup(input_id)?.handle == arg,
        control: ctx.expression_controls.get(&handle).copied(),
    });
}
if fun == Mf::Exp2 && self.correspondence.is_some() {
    self.exp2_imports.push(super::PendingExp2 {
        function_id: self.correspondence_function, result_id, type_id: result_type_id,
        set_id, instruction: inst_id, producer: handle, expected: ctx.expressions[handle].clone(),
        argument: arg, input_id,
        direct: self.lookup_expression.lookup(input_id)?.handle == arg,
        control: ctx.expression_controls.get(&handle).copied(),
    });
}
self.lookup_expression.insert(result_id, LookupExpression { handle, type_id: result_type_id, block_id });

// FPFastMathMode None is admitted only on OpFOrdLessThan
// over one f32 scalar/vector type with the matching bool result.
let Some((result_id, type_id, handle, ids)) = self.last_binary865.take() else {
    return Err(Error::UnsupportedExp2Control(0));
};
let crate::Expression::Binary { left, right, .. } = ctx.expressions[handle] else {
    return Err(Error::UnsupportedExp2Control(result_id));
};
if self.pending_exp2.remove(&result_id) {
    let inner = |id| self.lookup_type.get(&id).map(|t| ctx.module.types[t.handle].inner.clone());
    let l = inner(self.lookup_expression.lookup(ids[0])?.type_id);
    let r = inner(self.lookup_expression.lookup(ids[1])?.type_id);
    let shaped = l == r && match (l.clone(), inner(type_id)) {
        (Some(crate::TypeInner::Scalar(crate::Scalar::F32)), Some(crate::TypeInner::Scalar(crate::Scalar::BOOL))) => true,
        (Some(crate::TypeInner::Vector { size, scalar: crate::Scalar::F32 }),
         Some(crate::TypeInner::Vector { size: s, scalar: crate::Scalar::BOOL })) => size == s,
        _ => false,
    };
    if inst.op != Op::FOrdLessThan || !shaped {
        return Err(Error::UnsupportedExp2Control(result_id));
    }
    ctx.expression_controls.insert(handle, crate::ArithmeticControl::LessF32NoRefactoringV1);
}
if !matches!(inst.op, Op::LogicalEqual | Op::LogicalNotEqual) && self.correspondence.is_some() {
    let direct = self.lookup_expression.lookup(ids[0])?.handle == left
        && self.lookup_expression.lookup(ids[1])?.handle == right;
    self.compare_imports865.push(super::PendingCompare865 {
        function_id: self.correspondence_function, result_id, type_id, opcode: inst.op as u32,
        producer: handle, expected: ctx.expressions[handle].clone(), arguments: [left, right],
        ids, direct, control: ctx.expression_controls.get(&handle).copied(),
    });
}

let condition_id = self.next()?;
let condition_lexp = self.lookup_expression.lookup(condition_id)?;
let condition = get_expr_handle!(condition_id, condition_lexp);
if self.correspondence.is_some() {
    self.flow_imports.push(super::PendingFlow {
        function_id: ctx.function_id,
        kind: super::PendingFlowKind::Selection { id: condition_id, condition },
        direct: condition == condition_lexp.handle,
        expected: vec![(condition, ctx.expressions[condition].clone())],
    });
}

/// Restrictions on optimizations of one arithmetic expression result.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[cfg_attr(feature = "serialize", derive(Serialize))]
#[cfg_attr(feature = "deserialize", derive(Deserialize))]
#[cfg_attr(feature = "arbitrary", derive(Arbitrary))]
pub enum ArithmeticControl {
    /// The operation must not contract with another operation or reassociate.
    ///
    /// This applies only to the decorated producer, not recursively to its
    /// operands or consumers. It does not specify a rounding mode, denormal
    /// handling, or the internal evaluation order of a dot product.
    NoContraction,
    /// Revision 1 transport permissions for exactly scalar-f32 Math(Exp2).
    /// Withhold all FPFastMathMode permissions (including reassociation,
    /// contraction, reciprocal/transform and NaN/Inf/signed-zero assumptions)
    /// on this producer. DXC lowers it to an isolated precise Exp2 intrinsic.
    /// Mutually exclusive with NoContraction via this single tagged map value.
    /// Does not recursively control arguments/consumers, guarantee numerical
    /// accuracy/flush behavior, or establish D3D source provenance. The caller
    /// must qualify those separately, including the protected consumer graph.
    Exp2F32NoRefactoringV1,
    /// Revision 1 transport permissions for exactly Math(Floor) whose
    /// argument and result are the same f32 scalar or f32 vector type
    /// (D3D `round_ni`). Withhold all FPFastMathMode permissions (including
    /// reassociation, contraction, reciprocal/transform and NaN/Inf/signed-zero
    /// assumptions) on this producer; HLSL isolates it as a precise floor.
    /// Mutually exclusive with the other controls via this single tagged map
    /// value. Does not specify denormal flushing (D3D `round_ni` maps a
    /// denormal input to a sign-preserving zero), does not recursively control
    /// arguments/consumers and establishes no D3D source provenance.
    FloorF32NoRefactoringV1,
    /// Revision 1 transport permissions for exactly Binary(Less) whose two
    /// operands are the same f32 scalar or f32 vector type and whose result is
    /// the bool scalar/vector of that size (D3D `lt`). Withhold all
    /// FPFastMathMode permissions (NotNaN/NotInf/NSZ assumptions,
    /// reassociation, transform) on this comparison: the ordered `<` must
    /// stay false for NaN and must not be inverted or refactored. HLSL
    /// isolates it in a non-inlined helper. Does not flush denormals itself:
    /// the D3D lowering flushes both operands explicitly before the compare.
    /// Establishes no D3D source provenance and controls no other expression.
    LessF32NoRefactoringV1,
    /// Revision 1 strict transport (FPFastMathMode None) for exactly
    /// Math(Sin | Cos | InverseSqrt) on one f32 scalar/vector type, or Binary(Divide) on one f32
    /// type: the precise D3D `sincos`, `rsq` and `div` whose accuracy is a documented tolerance.
    /// HLSL isolates each in a non-inlined precise helper. Specifies no accuracy, no denormal or
    /// special-value behaviour (the D3D lowering selects those in integer operations), and no
    /// source provenance; admission is a separate measured tolerance gate.
    ToleranceF32NoRefactoringV1,
    /// Carrier rule R4: strict transport (FPFastMathMode None) for exactly
    /// Binary(Add) on one f32 scalar/vector type: the producer of a precise D3D `add_sat`, whose
    /// saturate (NaN -> 0) needs NaN/Inf-exact addition; an exception to the R2 0x7 form.
    AddF32StrictV1,
}

/// Optimization restrictions attached to producing arithmetic expressions.
///
/// Controls are supported on scalar or equal-shaped vector addition,
/// subtraction, and multiplication, and on floating-point dot products.
/// Backends must reject controls they cannot preserve. These entries do not
/// keep otherwise unused expressions alive during compaction.
/// Controlled expressions and their consumers are runtime expressions: they
/// cannot be used as constant-or-override local variable initializers. Use
/// an emitted expression and a store for runtime initialization instead.
#[cfg_attr(feature = "deserialize", serde(default))]
pub expression_controls: FastIndexMap<Handle<Expression>, ArithmeticControl>,

/// Classify function expressions without folding controlled arithmetic into
/// constant-only contexts. Consumers must inherit the runtime requirement
/// while traversing the arena, not after their kinds have been computed.
pub(crate) fn from_function(function: &crate::Function) -> Self {
    let mut tracker = Self {
        inner: HandleVec::with_capacity(function.expressions.len()),
    };
    for (handle, expr) in function.expressions.iter() {
        let kind = if function.expression_controls.contains_key(&handle) {
            ExpressionKind::Runtime
        } else {
            tracker.type_of_with_expr(expr)
        };
        tracker.inner.insert(handle, kind);
    }
    tracker
}

}

pub(crate) fn append_runtime(
    &mut self,
    expr: Expression,
    span: Span,
) -> Result<Handle<Expression>, ConstantEvaluatorError> {
    if !self.behavior.has_runtime_restrictions() {
        return Err(ConstantEvaluatorError::RuntimeExpr);
    }
    Ok(self.append_expr(expr, span, ExpressionKind::Runtime))

/// Whether any function contains restricted arithmetic expressions.
pub fn has_arithmetic_controls(&self) -> bool {
    self.functions
        .iter()
        .any(|(_, f)| !f.expression_controls.is_empty())
        || self
            .entry_points
            .iter()
            .any(|e| !e.function.expression_controls.is_empty())
}

for (&handle, &control) in &fun.expression_controls {
    let valid = match control {
        crate::ArithmeticControl::Exp2F32NoRefactoringV1 => matches!(fun.expressions.try_get(handle), Ok(crate::Expression::Math { fun: crate::MathFunction::Exp2, arg1: None, arg2: None, arg3: None, .. })),
        crate::ArithmeticControl::FloorF32NoRefactoringV1 => matches!(fun.expressions.try_get(handle), Ok(crate::Expression::Math { fun: crate::MathFunction::Floor, arg1: None, arg2: None, arg3: None, .. })),
        crate::ArithmeticControl::LessF32NoRefactoringV1 => matches!(fun.expressions.try_get(handle), Ok(crate::Expression::Binary { op: crate::BinaryOperator::Less, .. })),
        crate::ArithmeticControl::AddF32StrictV1 => matches!(fun.expressions.try_get(handle), Ok(crate::Expression::Binary { op: crate::BinaryOperator::Add, .. })),
        crate::ArithmeticControl::ToleranceF32NoRefactoringV1 => matches!(fun.expressions.try_get(handle),
            Ok(crate::Expression::Math { fun: crate::MathFunction::Sin | crate::MathFunction::Cos | crate::MathFunction::InverseSqrt, arg1: None, arg2: None, arg3: None, .. })
            | Ok(crate::Expression::Binary { op: crate::BinaryOperator::Divide, .. })),
        crate::ArithmeticControl::NoContraction => matches!(
        fun.expressions.try_get(handle),
        Ok(crate::Expression::Binary {
            op: crate::BinaryOperator::Add
                | crate::BinaryOperator::Subtract
                | crate::BinaryOperator::Multiply,
            ..
        }) | Ok(crate::Expression::Math {
            fun: crate::MathFunction::Dot,
            ..
        })
    )};
    if !valid {
        return Err(FunctionError::InvalidArithmeticControl(handle).with_span());
    }
}

for &handle in fun.expression_controls.keys() {
    let valid = match fun.expressions[handle] {
        crate::Expression::Math { fun: crate::MathFunction::Exp2, arg, .. } =>
            *info[arg].ty.inner_with(&module.types) == crate::TypeInner::Scalar(crate::Scalar::F32)
            && *info[handle].ty.inner_with(&module.types) == crate::TypeInner::Scalar(crate::Scalar::F32),
        crate::Expression::Math { fun: crate::MathFunction::Floor, arg, .. } => {
            let argument = info[arg].ty.inner_with(&module.types);
            matches!(
                *argument,
                crate::TypeInner::Scalar(crate::Scalar::F32)
                    | crate::TypeInner::Vector { scalar: crate::Scalar::F32, .. }
            ) && argument == info[handle].ty.inner_with(&module.types)
        }
        crate::Expression::Math { fun: crate::MathFunction::Sin | crate::MathFunction::Cos | crate::MathFunction::InverseSqrt, arg, .. } => {
            let argument = info[arg].ty.inner_with(&module.types);
            matches!(*argument, crate::TypeInner::Scalar(crate::Scalar::F32) | crate::TypeInner::Vector { scalar: crate::Scalar::F32, .. })
                && argument == info[handle].ty.inner_with(&module.types)
        }
        crate::Expression::Binary { op: crate::BinaryOperator::Add, left, right }
            if fun.expression_controls[&handle] == crate::ArithmeticControl::AddF32StrictV1 =>
        {
            let l = info[left].ty.inner_with(&module.types);
            matches!(*l, crate::TypeInner::Scalar(crate::Scalar::F32) | crate::TypeInner::Vector { scalar: crate::Scalar::F32, .. })
                && l == info[right].ty.inner_with(&module.types)
        }
        crate::Expression::Binary { op: crate::BinaryOperator::Divide, left, right } => {
            let l = info[left].ty.inner_with(&module.types);
            matches!(*l, crate::TypeInner::Scalar(crate::Scalar::F32) | crate::TypeInner::Vector { scalar: crate::Scalar::F32, .. })
                && l == info[right].ty.inner_with(&module.types)
        }
        crate::Expression::Binary { op: crate::BinaryOperator::Less, left, right } => {
            // Only LessF32NoRefactoringV1 is valid on Less (checked above).
            let l = info[left].ty.inner_with(&module.types);
            let result = info[handle].ty.inner_with(&module.types);
            l == info[right].ty.inner_with(&module.types)
                && match (l, result) {
                    (crate::TypeInner::Scalar(crate::Scalar::F32), crate::TypeInner::Scalar(crate::Scalar::BOOL)) => true,
                    (crate::TypeInner::Vector { size, scalar: crate::Scalar::F32 },
                     crate::TypeInner::Vector { size: s, scalar: crate::Scalar::BOOL }) => size == s,
                    _ => false,
                }
        }
        crate::Expression::Binary { left, right, .. } => {
            matches!(
                info[left].ty.inner_with(&module.types),
                crate::TypeInner::Scalar(_) | crate::TypeInner::Vector { .. }
            ) && info[left].ty.inner_with(&module.types)
                == info[right].ty.inner_with(&module.types)
        }
        crate::Expression::Math {
            fun: crate::MathFunction::Dot,
            arg,
            ..
        } => matches!(
            info[arg].ty.inner_with(&module.types),
            crate::TypeInner::Vector {
                scalar: crate::Scalar {
                    kind: crate::ScalarKind::Float,
                    ..
                },
                ..
            }
        ),
        _ => false,
    };
    if !valid {
        return Err(FunctionError::InvalidArithmeticControl(handle).with_span());
    }
}

    Self::validate_expression_handle(handle, expressions)?;
}
